import type { IsoTimestamp, OrgId, UserId } from "./common";

export type ApiTokenScope = "read" | "write";

/**
 * A personal API token as callers see it. The secret is shown once, when the
 * token is created, and never stored; neither it nor any hash of it appears on
 * this type.
 */
export interface ApiToken {
  id: string;
  orgId: OrgId;
  userId: UserId;
  name: string;
  scope: ApiTokenScope;
  prefix: string;
  expiresAt: IsoTimestamp;
  lastUsedAt: IsoTimestamp | null;
  revokedAt: IsoTimestamp | null;
  createdAt: IsoTimestamp;
}
