/**
 * Personal API tokens: issue, list, revoke, and authenticate a bearer secret.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, hashToken, randomToken
 */
import { emit } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { actorEnvelope, envelope, orgResource, requireFound } from "./_support";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";

/** Most usable (unrevoked, unexpired) tokens one user may hold per organization. */
const MAX_USABLE_TOKENS = 5;

const TOKEN_PREFIX = "tfk_";
const TOKEN_RANDOM_BYTES = 32;
const DISPLAY_PREFIX_LENGTH = 12;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Mints a token. The secret is returned here and nowhere else. */
export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);
  if (parsed.scope === "write") {
    assertCan(actor, "api_token:create_write", orgResource(parsed.orgId));
  }

  const token = `${TOKEN_PREFIX}${randomToken(TOKEN_RANDOM_BYTES)}`;
  const now = new Date();
  const createdAt = toIsoTimestamp(now);

  const apiToken = await apiTokenRepo.insertApiTokenWithinLimit(
    {
      orgId: parsed.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      prefix: token.slice(0, DISPLAY_PREFIX_LENGTH),
      tokenHash: hashToken(token),
      expiresAt: toIsoTimestamp(
        new Date(now.getTime() + parsed.expiresInDays * MS_PER_DAY),
      ),
      createdAt,
    },
    MAX_USABLE_TOKENS,
    createdAt,
  );
  if (apiToken === null) {
    throw new Error(
      `You can hold at most ${MAX_USABLE_TOKENS} active API tokens per organization`,
    );
  }

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    name: apiToken.name,
    scope: apiToken.scope,
    prefix: apiToken.prefix,
    expiresAt: apiToken.expiresAt,
  });

  return { token, apiToken };
}

export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId: UserId = actor.userId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  if (userId !== actor.userId) {
    assertCan(actor, "api_token:manage_others", orgResource(orgId));
  }
  return apiTokenRepo.listApiTokens(orgId, userId);
}

/** Idempotent: an already-revoked token is returned as is and nothing is audited. */
export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const existing = requireFound(
    await apiTokenRepo.findApiToken(orgId, tokenId),
    "API token",
    tokenId,
  );
  if (existing.userId !== actor.userId) {
    assertCan(actor, "api_token:manage_others", orgResource(orgId));
  }
  if (existing.revokedAt !== null) return existing;

  const revoked = await apiTokenRepo.revokeApiToken(
    orgId,
    tokenId,
    toIsoTimestamp(new Date()),
  );
  // Lost a race with a concurrent revoke: that call owns the audit row.
  if (revoked === null) {
    return requireFound(
      await apiTokenRepo.findApiToken(orgId, tokenId),
      "API token",
      tokenId,
    );
  }

  await emitRevoked(actor.orgId, actor.userId, revoked);
  return revoked;
}

/**
 * Revokes every live token `userId` holds in the actor's organization, for when
 * that member has just been removed. Already-revoked tokens are left alone.
 */
export async function revokeTokensOfRemovedMember(
  actor: Actor,
  userId: UserId,
): Promise<void> {
  const revoked = await apiTokenRepo.revokeAllApiTokensForUser(
    actor.orgId,
    userId,
    toIsoTimestamp(new Date()),
  );
  for (const apiToken of revoked) {
    await emitRevoked(actor.orgId, actor.userId, apiToken);
  }
}

/**
 * Resolves a bearer secret to the `Actor` it speaks for, or `null`. A read
 * token is always a viewer; a write token carries the member's current role.
 */
export async function authenticateApiToken(token: string): Promise<Actor | null> {
  if (typeof token !== "string" || token.length === 0) return null;

  const apiToken = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (apiToken === null || apiToken.revokedAt !== null) return null;

  const now = toIsoTimestamp(new Date());
  if (apiToken.expiresAt <= now) return null;

  const org = await orgRepo.findOrgById(apiToken.orgId);
  if (org === null || org.archivedAt !== null) return null;

  const member = await memberRepo.findMember(apiToken.orgId, apiToken.userId);
  if (member === null || member.status !== "active") return null;

  await apiTokenRepo.touchApiTokenLastUsed(apiToken.orgId, apiToken.id, now);

  return {
    userId: apiToken.userId,
    orgId: apiToken.orgId,
    role: apiToken.scope === "read" ? "viewer" : member.role,
  };
}

async function emitRevoked(
  orgId: OrgId,
  actorId: UserId,
  apiToken: ApiToken,
): Promise<void> {
  await emit("api_token.revoked", {
    ...envelope(orgId, actorId),
    tokenId: apiToken.id,
    tokenUserId: apiToken.userId,
    name: apiToken.name,
  });
}
