describe("api tokens", () => {
  it("works", async () => {
    const t = await createTenant("tok");
    const { member, viewer, admin } = t.actors;
    const o = t.org.id;
    await expect(svc.createApiToken(member, { orgId: o, name: "  ", scope: "read", expiresInDays: 1 })).rejects.toBeInstanceOf(ZodError);
    await expect(svc.createApiToken(viewer, { orgId: o, name: "a", scope: "write", expiresInDays: 1 })).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(svc.createApiToken(viewer, { orgId: "01HZZZPPPPPPPPPPPPPPPPPPPP" as never, name: "a", scope: "read", expiresInDays: 1 })).rejects.toBeInstanceOf(TenantScopeError);
    const r = await svc.createApiToken(viewer, { orgId: o, name: " v ", scope: "read", expiresInDays: 1 });
    expect(r.apiToken.name).toBe("v");
    expect(r.token.startsWith("tfk_")).toBe(true);
    expect(r.apiToken.prefix).toBe(r.token.slice(0, 12));
    expect(await svc.authenticateApiToken(r.token)).toEqual({ userId: viewer.userId, orgId: o, role: "viewer" });
    const w = await svc.createApiToken(member, { orgId: o, name: "w", scope: "write", expiresInDays: 1 });
    expect((await svc.authenticateApiToken(w.token))?.role).toBe("member");
    const list = await svc.listApiTokens(member, o);
    expect(list.length).toBe(1);
    expect((await svc.listApiTokens(member, o))[0]?.lastUsedAt).not.toBeNull();
    await expect(svc.listApiTokens(member, o, viewer.userId)).rejects.toBeInstanceOf(PermissionDeniedError);
    expect((await svc.listApiTokens(admin, o, viewer.userId)).length).toBe(1);
    for (let i = 0; i < 4; i++) await svc.createApiToken(member, { orgId: o, name: "x" + i, scope: "read", expiresInDays: 1 });
    await expect(svc.createApiToken(member, { orgId: o, name: "six", scope: "read", expiresInDays: 1 })).rejects.toThrow();
    const l2 = await svc.listApiTokens(member, o);
    expect(l2.length).toBe(5);
    expect(l2[0]?.name).toBe("x3");
    await svc.revokeApiToken(member, o, l2[0]!.id);
    await svc.revokeApiToken(member, o, l2[0]!.id);
    await expect(svc.revokeApiToken(viewer, o, l2[1]!.id)).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(svc.revokeApiToken(viewer, o, "nope")).rejects.toThrow(/not found/);
    // remove member
    const m = await memberRepo.findMember(o, member.userId);
    await memberService.removeMember(t.actors.owner, { orgId: o, memberId: m!.id });
    expect(await svc.authenticateApiToken(w.token)).toBeNull();
    const all = await svc.listApiTokens(admin, o, member.userId);
    expect(all.every((x) => x.revokedAt !== null)).toBe(true);
    const page = await activityRepo.listActivity({ orgId: o, limit: 100, cursor: null } as never);
    const acts = page.items.map((e) => `${e.action}:${e.actorId === t.actors.owner.userId ? "owner" : "other"}`);
    console.log(acts);
    expect(page.items.filter((e) => e.action === "api_token.revoked").length).toBe(5 + 0 + 0 - 0 - 0 + 0 > 0 ? 6 : 0);
    expect(JSON.stringify(page.items)).not.toContain(w.token);
  });
});
